CREATE TABLE IF NOT EXISTS webhook_subscriptions (id VARCHAR(36), team_id VARCHAR(36) NOT NULL, url VARCHAR(2048) NOT NULL, `types` VARCHAR(600) NOT NULL, description VARCHAR(200) NOT NULL, enabled BOOLEAN NOT NULL, disabled_reason VARCHAR(64) NULL, secret text NOT NULL, created_by VARCHAR(36) NOT NULL, credential_id VARCHAR(36) NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, version INT NOT NULL, fanout_seq BIGINT NOT NULL, failures INT NOT NULL, CONSTRAINT pk_webhook_subscriptions PRIMARY KEY (id));
CREATE INDEX webhook_subscription_team ON webhook_subscriptions (team_id, created_at);